💼 Proyecto: Juego “Adivina el Número”
import random

numero_secreto = random.randint(1, 100)
intentos = 0
adivinó = False

print("¡Bienvenido al juego Adivina el Número!")
print("Tengo un número del 1 al 100. ¿Puedes adivinar?")

while not adivinó:
    try:
        número_usuario = int(input("Tu número: "))
        intentos += 1

        if número_usuario &lt; numero_secreto:
            print("Mi número es mayor")
        elif número_usuario &gt; numero_secreto:
            print("Mi número es menor")
        else:
            print(f"¡Lo adivinaste en {intentos} intentos!")
            adivinó = True
    except ValueError:
        print("Debes ingresar un número válido")

